const VOICE_PREFERENCES = {
  omkar_ai: {
    preferred: ['Google UK English Male', 'Microsoft David', 'Alex', 'Daniel'],
    gender: 'male',
    fallbackLang: 'en-GB'
  },
  priya_biology: {
    preferred: ['Google UK English Female', 'Microsoft Zira', 'Samantha', 'Victoria'],
    gender: 'female',
    fallbackLang: 'en-US'
  }
};

let availableVoices = [];
let voicesLoaded = false;
let currentUtterance = null;
let utteranceQueue = []; // ✅ QUEUE FOR LONG SENTENCES

const loadVoices = () => {
  return new Promise((resolve) => {
    availableVoices = window.speechSynthesis.getVoices();

    if (availableVoices.length > 0) {
      voicesLoaded = true;
      console.log('🎤 Loaded', availableVoices.length, 'voices');
      resolve(availableVoices);
    } else {
      window.speechSynthesis.onvoiceschanged = () => {
        availableVoices = window.speechSynthesis.getVoices();
        voicesLoaded = true;
        console.log('🎤 Loaded', availableVoices.length, 'voices');
        resolve(availableVoices);
      };

      setTimeout(() => {
        availableVoices = window.speechSynthesis.getVoices();
        voicesLoaded = true;
        resolve(availableVoices);
      }, 1000);
    }
  });
};

const findBestVoice = (companionId) => {
  if (availableVoices.length === 0) return null;

  const prefs = VOICE_PREFERENCES[companionId] || VOICE_PREFERENCES.omkar_ai;

  for (const voiceName of prefs.preferred) {
    const voice = availableVoices.find(v => v.name.includes(voiceName));
    if (voice) {
      console.log(`✅ Using: ${voice.name}`);
      return voice;
    }
  }

  const genderVoice = availableVoices.find(v => 
    v.lang.startsWith('en') && 
    (prefs.gender === 'male' ? 
      v.name.toLowerCase().includes('male') || v.name.toLowerCase().includes('david') :
      v.name.toLowerCase().includes('female') || v.name.toLowerCase().includes('zira')
    )
  );

  if (genderVoice) return genderVoice;

  return availableVoices.find(v => v.lang.startsWith('en')) || availableVoices[0];
};

// ✅ FIXED: Split long text into chunks
const splitIntoChunks = (text, maxLength = 200) => {
  const sentences = text.match(/[^.!?]+[.!?]+/g) || [text];
  const chunks = [];
  let currentChunk = '';

  for (const sentence of sentences) {
    if ((currentChunk + sentence).length > maxLength && currentChunk) {
      chunks.push(currentChunk.trim());
      currentChunk = sentence;
    } else {
      currentChunk += ' ' + sentence;
    }
  }

  if (currentChunk.trim()) {
    chunks.push(currentChunk.trim());
  }

  return chunks;
};

export const speakText = async (text, companionId = 'omkar_ai') => {
  if (!window.speechSynthesis) {
    console.warn('⚠️ Browser TTS not supported');
    return Promise.resolve();
  }

  if (!text || !text.trim()) {
    console.warn('⚠️ Empty text');
    return Promise.resolve();
  }

  // Stop any ongoing speech
  try {
    window.speechSynthesis.cancel();
    currentUtterance = null;
    utteranceQueue = [];
  } catch (e) {
    console.warn('Cancel failed:', e);
  }

  await new Promise(resolve => setTimeout(resolve, 150));

  if (!voicesLoaded) {
    await loadVoices();
  }

  // ✅ Split long text into chunks
  const chunks = splitIntoChunks(text, 200);
  console.log(`🎤 Speaking ${chunks.length} chunks`);

  return new Promise((resolve, reject) => {
    let chunkIndex = 0;

    const speakNextChunk = () => {
      if (chunkIndex >= chunks.length) {
        console.log('✅ All chunks spoken');
        resolve();
        return;
      }

      const chunkText = chunks[chunkIndex];
      chunkIndex++;

      try {
        const utterance = new SpeechSynthesisUtterance(chunkText);
        currentUtterance = utterance;

        const bestVoice = findBestVoice(companionId);
        if (bestVoice) {
          utterance.voice = bestVoice;
          utterance.lang = bestVoice.lang;
        } else {
          utterance.lang = 'en-US';
        }

        utterance.rate = 0.95;
        utterance.pitch = companionId === 'omkar_ai' ? 0.9 : 1.1;
        utterance.volume = 1.0;

        utterance.onend = () => {
          console.log(`✅ Chunk ${chunkIndex} finished`);
          setTimeout(speakNextChunk, 100); // Small delay between chunks
        };

        utterance.onerror = (event) => {
          console.error('❌ Speech error:', event.error);

          if (event.error === 'interrupted' || event.error === 'canceled') {
            resolve();
          } else {
            // Try next chunk on error
            speakNextChunk();
          }
        };

        console.log(`🎤 Speaking chunk ${chunkIndex}: "${chunkText.substring(0, 50)}..."`);
        window.speechSynthesis.speak(utterance);

      } catch (error) {
        console.error('❌ Speech setup error:', error);
        speakNextChunk(); // Try next chunk
      }
    };

    speakNextChunk();

    // Safety timeout
    setTimeout(() => {
      currentUtterance = null;
      console.warn('⚠️ Speech timeout');
      window.speechSynthesis.cancel();
      resolve();
    }, chunks.length * 15000); // 15 seconds per chunk
  });
};

export const stopSpeaking = () => {
  try {
    if (window.speechSynthesis) {
      window.speechSynthesis.cancel();
      currentUtterance = null;
      utteranceQueue = [];
      console.log('⏹️ Stopped speech');
    }
  } catch (e) {
    console.warn('Stop failed:', e);
  }
};

export const isSpeechSupported = () => {
  return 'speechSynthesis' in window;
};

if (typeof window !== 'undefined') {
  loadVoices();

  window.addEventListener('beforeunload', () => {
    stopSpeaking();
  });
}
